<#
.SYNOPSIS
  ECHO v2.1.9 - Event Correlation & History Observer (WPF Edition)
.DESCRIPTION
  Read-only, dark-themed event explorer for Windows, Azure Local and offline SDDC EVTX.
  Live nodes, optional cluster discovery, SDDC node tabs, correlation, filters and CSV export.
.USAGE
  powershell.exe -NoProfile -STA -ExecutionPolicy Bypass -File .\ECHO-WPF-v2.0.ps1
.NOTES
  Windows PowerShell 5.1, Windows 10/11 or Windows Server with desktop experience.
  Run elevated to access protected channels. Remote queries require Event Log permissions.
  The viewer does not alter event logs. Queries are capped at 1500 events per log/node.
#>
#Requires -Version 5.1
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml

$script:Version='2.1.9'
$script:Items=New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:VisibleItems=New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:Sessions=@{}
$script:CurrentSession=$null
$script:CurrentLog=$null
$script:LastResults=@()
$script:CurrentJob=$null
$script:JobTimer=$null
$script:JobError=$null
$script:SettingsFolder=Join-Path $env:APPDATA 'ECHO'
$script:SettingsFile=Join-Path $script:SettingsFolder 'LastSDDCFolder.txt'
$script:LoadingTree=$false
$script:CancelRequested=$false
$script:MaxEvents=1500
# Each imported SDDC collection receives one distinct, reusable tab color.
$script:SDDCGroupColors=@('#126A8A','#7850A5','#A45B2A','#287B61','#9A3D67','#5A69A8','#8A7130','#397C91','#795D88','#4D8041')
$script:SDDCGroupColorIndex=0
$script:SDDCGroupColorByRoot=@{}


[xml]$xaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="ECHO - Event Explorer" Width="1320" Height="820" MinWidth="800" MinHeight="580" SizeToContent="Manual"
        WindowStartupLocation="CenterScreen" WindowStyle="SingleBorderWindow" ResizeMode="CanResize" ShowInTaskbar="True" Background="#061727" Foreground="#E8F4FF"
        FontFamily="Segoe UI" FontSize="12" UseLayoutRounding="True" SnapsToDevicePixels="True">
 <Window.Resources>
  <SolidColorBrush x:Key="Surface" Color="#0A2034"/>
  <SolidColorBrush x:Key="Deep" Color="#071827"/>
  <SolidColorBrush x:Key="Edge" Color="#23465E"/>
  <SolidColorBrush x:Key="Cyan" Color="#46CBFF"/>
  <SolidColorBrush x:Key="Text" Color="#E8F4FF"/>
  <SolidColorBrush x:Key="Muted" Color="#91B3CC"/>
  <Style TargetType="Button" x:Key="ActionButton">
   <Setter Property="Background" Value="#112A40"/><Setter Property="Foreground" Value="#D9F2FF"/>
   <Setter Property="BorderBrush" Value="#34556D"/><Setter Property="BorderThickness" Value="1"/>
   <Setter Property="Padding" Value="13,7"/><Setter Property="Margin" Value="4,0"/>
   <Setter Property="Cursor" Value="Hand"/><Setter Property="MinHeight" Value="31"/>
   <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button">
    <Border x:Name="Border" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
            BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="5" Padding="{TemplateBinding Padding}">
      <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Border>
    <ControlTemplate.Triggers>
     <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Border" Property="Background" Value="#1C4563"/><Setter Property="Foreground" Value="#FFFFFF"/></Trigger>
     <Trigger Property="IsPressed" Value="True"><Setter TargetName="Border" Property="Background" Value="#0875BE"/></Trigger>
     <Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.45"/></Trigger>
    </ControlTemplate.Triggers>
   </ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="TextBox">
   <Setter Property="Background" Value="#0D263B"/><Setter Property="Foreground" Value="#ECF8FF"/>
   <Setter Property="BorderBrush" Value="#365B74"/><Setter Property="BorderThickness" Value="1"/>
   <Setter Property="Padding" Value="9,6"/><Setter Property="CaretBrush" Value="#51D6FF"/>
  </Style>
  <Style TargetType="ComboBox">
   <Setter Property="Background" Value="#122D43"/><Setter Property="Foreground" Value="#FFFFFF"/>
   <Setter Property="BorderBrush" Value="#365B74"/><Setter Property="Padding" Value="5"/>
  </Style>
  <Style TargetType="ComboBoxItem">
   <Setter Property="Foreground" Value="#FFFFFF"/><Setter Property="Background" Value="#102A40"/>
   <Setter Property="Padding" Value="9,6"/>
   <Style.Triggers>
    <Trigger Property="IsHighlighted" Value="True"><Setter Property="Background" Value="#B8E8FF"/><Setter Property="Foreground" Value="#000000"/></Trigger>
    <Trigger Property="IsSelected" Value="True"><Setter Property="Background" Value="#B8E8FF"/><Setter Property="Foreground" Value="#000000"/></Trigger>
   </Style.Triggers>
  </Style>
  <Style TargetType="CheckBox">
   <Setter Property="Foreground" Value="#F2F9FF"/>
   <Setter Property="Background" Value="#0C2A40"/>
   <Setter Property="FontSize" Value="13"/>
   <Style.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter Property="Foreground" Value="#FFFFFF"/></Trigger></Style.Triggers>
  </Style>
  <Style TargetType="ToggleButton" x:Key="LevelToggle">
   <Setter Property="Foreground" Value="#FFFFFF"/><Setter Property="Background" Value="#173D5B"/>
   <Setter Property="BorderBrush" Value="#4A85A6"/><Setter Property="Padding" Value="9,5"/>
   <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ToggleButton">
    <Border x:Name="LevelBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="4" Padding="{TemplateBinding Padding}">
     <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Border>
    <ControlTemplate.Triggers>
     <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="LevelBorder" Property="Background" Value="#21648C"/><Setter Property="Foreground" Value="#FFFFFF"/></Trigger>
     <Trigger Property="IsChecked" Value="True"><Setter TargetName="LevelBorder" Property="Background" Value="#15517B"/><Setter Property="Foreground" Value="#FFFFFF"/></Trigger>
    </ControlTemplate.Triggers>
   </ControlTemplate></Setter.Value></Setter>
  </Style>
  <!-- Custom template prevents Windows Server theme from replacing hover/selection brushes. -->
  <Style TargetType="TreeViewItem">
   <Setter Property="Foreground" Value="#E8F4FF"/>
   <Setter Property="Background" Value="Transparent"/>
   <Setter Property="IsExpanded" Value="False"/>
   <Setter Property="Template"><Setter.Value>
    <ControlTemplate TargetType="TreeViewItem">
     <StackPanel>
      <Border x:Name="ItemSurface" Background="Transparent" CornerRadius="3" Margin="1" Padding="2,3" HorizontalAlignment="Stretch">
       <DockPanel LastChildFill="True">
        <ToggleButton x:Name="Expander" DockPanel.Dock="Left" Width="17" Height="18"
                      IsChecked="{Binding IsExpanded,RelativeSource={RelativeSource TemplatedParent},Mode=TwoWay}"
                      Focusable="False" Background="Transparent" BorderThickness="0" Foreground="#A8C8DD">
         <ToggleButton.Template><ControlTemplate TargetType="ToggleButton">
          <Grid Width="17" Height="18">
           <Path x:Name="Chevron" Data="M 6 4 L 11 9 L 6 14" Stroke="{TemplateBinding Foreground}" StrokeThickness="1.6" HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Grid>
          <ControlTemplate.Triggers>
           <Trigger Property="IsChecked" Value="True"><Setter TargetName="Chevron" Property="Data" Value="M 4 6 L 9 11 L 14 6"/></Trigger>
          </ControlTemplate.Triggers>
         </ControlTemplate></ToggleButton.Template>
        </ToggleButton>
        <ContentPresenter x:Name="HeaderPresenter" ContentSource="Header" VerticalAlignment="Center"/>
       </DockPanel>
      </Border>
      <ItemsPresenter x:Name="Children" Margin="17,0,0,0" Visibility="Collapsed"/>
     </StackPanel>
     <ControlTemplate.Triggers>
      <Trigger Property="HasItems" Value="False"><Setter TargetName="Expander" Property="Visibility" Value="Hidden"/></Trigger>
      <Trigger Property="IsExpanded" Value="True"><Setter TargetName="Children" Property="Visibility" Value="Visible"/></Trigger>
      <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="ItemSurface" Property="Background" Value="#17425F"/><Setter Property="Foreground" Value="#FFFFFF"/></Trigger>
      <Trigger Property="IsSelected" Value="True"><Setter TargetName="ItemSurface" Property="Background" Value="#B8E8FF"/><Setter Property="Foreground" Value="#000000"/></Trigger>
      <MultiTrigger><MultiTrigger.Conditions><Condition Property="IsSelected" Value="True"/><Condition Property="IsMouseOver" Value="True"/></MultiTrigger.Conditions>
       <Setter TargetName="ItemSurface" Property="Background" Value="#B8E8FF"/><Setter Property="Foreground" Value="#000000"/>
      </MultiTrigger>
     </ControlTemplate.Triggers>
    </ControlTemplate>
   </Setter.Value></Setter>
  </Style>
  <Style TargetType="TabItem">
   <Setter Property="Foreground" Value="#E2F4FF"/><Setter Property="Background" Value="#112B43"/>
   <Setter Property="Padding" Value="15,7"/><Setter Property="Margin" Value="0,0,3,0"/>
   <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="TabItem">
    <Border x:Name="Border" Background="{TemplateBinding Background}" BorderBrush="#31536C" BorderThickness="1,1,1,0" CornerRadius="5,5,0,0" Padding="{TemplateBinding Padding}">
     <ContentPresenter ContentSource="Header" TextElement.Foreground="{TemplateBinding Foreground}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Border>
    <ControlTemplate.Triggers>
     <Trigger Property="IsSelected" Value="True"><Setter TargetName="Border" Property="BorderBrush" Value="#FFFFFF"/><Setter TargetName="Border" Property="BorderThickness" Value="2,2,2,0"/></Trigger>
     <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Border" Property="BorderBrush" Value="#48CFFF"/></Trigger>
    </ControlTemplate.Triggers>
   </ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="DataGrid">
   <Setter Property="Background" Value="#081C2C"/><Setter Property="Foreground" Value="#E6F4FF"/>
   <Setter Property="BorderThickness" Value="0"/><Setter Property="RowBackground" Value="#0B2031"/>
   <Setter Property="AlternatingRowBackground" Value="#0E293D"/>
   <Setter Property="HorizontalGridLinesBrush" Value="#1B3A4E"/><Setter Property="VerticalGridLinesBrush" Value="#1B3A4E"/>
   <Setter Property="GridLinesVisibility" Value="Horizontal"/><Setter Property="HeadersVisibility" Value="Column"/>
   <Setter Property="CanUserReorderColumns" Value="True"/><Setter Property="CanUserResizeColumns" Value="True"/>
   <Setter Property="CanUserSortColumns" Value="True"/><Setter Property="RowHeight" Value="27"/>
   <Setter Property="SelectionMode" Value="Single"/><Setter Property="SelectionUnit" Value="FullRow"/>
   <Setter Property="IsReadOnly" Value="True"/><Setter Property="AutoGenerateColumns" Value="False"/>
  </Style>
  <Style TargetType="DataGridCell">
   <Style.Triggers><Trigger Property="IsSelected" Value="True"><Setter Property="Foreground" Value="Black"/><Setter Property="Background" Value="#B8E8FF"/></Trigger></Style.Triggers>
  </Style>
  <Style x:Key="EchoCellText" TargetType="TextBlock">
   <Setter Property="Foreground" Value="#E6F4FF"/>
   <Setter Property="TextWrapping" Value="NoWrap"/>
   <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
   <Style.Triggers>
    <DataTrigger Binding="{Binding IsSelected, RelativeSource={RelativeSource AncestorType={x:Type DataGridRow}}}" Value="True">
     <Setter Property="Foreground" Value="#000000"/>
    </DataTrigger>
   </Style.Triggers>
  </Style>
  <Style TargetType="DataGridColumnHeader">
   <Setter Property="Background" Value="#122F46"/><Setter Property="Foreground" Value="#CFE9FA"/>
   <Setter Property="Padding" Value="9,8"/><Setter Property="BorderBrush" Value="#2D5067"/>
   <Setter Property="BorderThickness" Value="0,0,1,1"/><Setter Property="FontWeight" Value="SemiBold"/>
  </Style>
  <Style TargetType="DataGridRow">
   <Setter Property="Foreground" Value="#E7F4FF"/>
   <Style.Triggers><Trigger Property="IsSelected" Value="True"><Setter Property="Background" Value="#B8E8FF"/><Setter Property="Foreground" Value="#000000"/></Trigger></Style.Triggers>
  </Style>
 </Window.Resources>
 <Grid Margin="8">
  <Grid.RowDefinitions>
   <RowDefinition Height="108"/><RowDefinition Height="43"/><RowDefinition Height="43"/>
   <RowDefinition Height="38"/><RowDefinition Height="*"/><RowDefinition Height="30"/>
  </Grid.RowDefinitions>
  <!-- Branded masthead -->
  <Border Grid.Row="0" Background="#031525" CornerRadius="8,8,0,0" BorderBrush="#1A4565" BorderThickness="1">
   <Grid Margin="10,4">
    <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <Image x:Name="BrandIcon" Grid.Column="0" Width="360" Height="96" Stretch="Uniform" HorizontalAlignment="Left" VerticalAlignment="Center"/>
    <StackPanel Grid.Column="2" VerticalAlignment="Center" HorizontalAlignment="Right" Margin="16,0,8,0">
     <TextBlock Text="EVENT CORRELATION &amp; HISTORY OBSERVER" FontWeight="SemiBold" FontSize="13" Foreground="#45CCFF" HorizontalAlignment="Right"/>
     <TextBlock Text="Windows Server   &#x2022;   Azure Local   &#x2022;   SDDC" Foreground="#A3D8F5" FontSize="11" Margin="0,8,0,0" HorizontalAlignment="Right"/>
     <TextBlock x:Name="VersionText" Text="v2.1.8" Foreground="#58D1FF" FontSize="11" Margin="0,8,0,0" HorizontalAlignment="Right"/>
    </StackPanel>
   </Grid>
  </Border>
  <!-- Icon navigation -->
  <Border Grid.Row="1" Background="#10293D" BorderBrush="#254A63" BorderThickness="1,0,1,1">
   <UniformGrid Columns="3" Margin="5,2">
    <Button x:Name="NavEvents" Style="{StaticResource ActionButton}" Background="#0879C9"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center"><TextBlock Text="&#x25A3;" FontSize="15" Foreground="#79D9FF" Margin="0,0,10,0"/><TextBlock Text="Events" FontSize="12"/></StackPanel></Button>
    <Button x:Name="NavExport" Style="{StaticResource ActionButton}"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center"><TextBlock Text="&#x21E7;" FontSize="17" Foreground="#79D9FF" Margin="0,0,10,0"/><TextBlock Text="Export" FontSize="12"/></StackPanel></Button>
    <Button x:Name="NavSettings" Style="{StaticResource ActionButton}"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center"><TextBlock Text="&#x2699;" FontSize="17" Foreground="#79D9FF" Margin="0,0,10,0"/><TextBlock Text="Settings" FontSize="12"/></StackPanel></Button>
   </UniformGrid>
  </Border>
  <!-- Search/filter bar integrated with results -->
  <Border Grid.Row="2" Background="#0B2236" BorderBrush="#21445A" BorderThickness="1,0,1,1">
   <DockPanel Margin="9,5" LastChildFill="True">
    <Button x:Name="BtnRefresh" DockPanel.Dock="Right" Style="{StaticResource ActionButton}" Content="&#x27F3;" FontSize="20" Padding="12,0" ToolTip="Refresh selected log"/>
    <Button x:Name="BtnStop" DockPanel.Dock="Right" Style="{StaticResource ActionButton}" Content="&#x25A0; Stop"/>
    <Button x:Name="BtnOpenSDDC" DockPanel.Dock="Right" Style="{StaticResource ActionButton}" Content="Open EVTX Folder"/>
    <ComboBox x:Name="TimeFilter" DockPanel.Dock="Right" Width="140" Margin="5,0" SelectedIndex="1" Foreground="#000000" Background="#E1F3FF" ToolTip="Timeline / time range">
     <ComboBoxItem Content="All Time" Foreground="Black"/><ComboBoxItem Content="Last 1 hour" Foreground="Black"/><ComboBoxItem Content="Last 6 hours" Foreground="Black"/>
     <ComboBoxItem Content="Last 24 hours" Foreground="Black"/><ComboBoxItem Content="Last 7 days" Foreground="Black"/><ComboBoxItem Content="Last 30 days" Foreground="Black"/>
    </ComboBox>
    <Grid DockPanel.Dock="Right" Width="150" Margin="5,0">
     <ToggleButton x:Name="LevelPicker" Style="{StaticResource LevelToggle}" Content="Levels: All" />
     <Popup x:Name="LevelPopup" PlacementTarget="{Binding ElementName=LevelPicker}" Placement="Bottom" StaysOpen="False" AllowsTransparency="True" IsOpen="{Binding IsChecked,ElementName=LevelPicker,Mode=TwoWay}">
      <Border Background="#102B40" BorderBrush="#3988B5" BorderThickness="1" CornerRadius="5" Padding="12" MinWidth="175">
       <StackPanel>
        <TextBlock Text="Show event levels" Foreground="#8EDBFF" FontWeight="SemiBold" Margin="0,0,0,8"/>
        <CheckBox x:Name="LevelCritical" Content="Critical" IsChecked="True" Margin="0,3"/>
        <CheckBox x:Name="LevelError" Content="Error" IsChecked="True" Margin="0,3"/>
        <CheckBox x:Name="LevelWarning" Content="Warning" IsChecked="True" Margin="0,3"/>
        <CheckBox x:Name="LevelInformation" Content="Information" IsChecked="True" Margin="0,3"/>
        <CheckBox x:Name="LevelVerbose" Content="Verbose" IsChecked="True" Margin="0,3"/>
        <Separator Margin="0,8"/>
        <StackPanel Orientation="Horizontal">
         <Button x:Name="LevelAll" Content="All" Style="{StaticResource ActionButton}" Padding="12,4" Margin="0,0,7,0"/>
         <Button x:Name="LevelNone" Content="None" Style="{StaticResource ActionButton}" Padding="12,4"/>
        </StackPanel>
       </StackPanel>
      </Border>
     </Popup>
    </Grid>
    <TextBlock x:Name="EventCount" DockPanel.Dock="Left" Text="Events (0)" FontSize="14" FontWeight="SemiBold" Foreground="#E8F4FF" Width="125" VerticalAlignment="Center"/>
    <TextBox x:Name="SearchBox" VerticalContentAlignment="Center" ToolTip="Filter by message, event ID, provider, computer or log"/>
   </DockPanel>
  </Border>
  <!-- Tabs for nodes -->
  <DockPanel Grid.Row="3" Background="#061727">
   <Button x:Name="BtnAddNode" DockPanel.Dock="Right" Content="&#xFF0B;" Style="{StaticResource ActionButton}" Margin="3,4" Padding="12,2" ToolTip="Add remote computer"/>
   <TabControl x:Name="NodeTabs" Background="#061727" BorderThickness="0" Margin="2,4,0,0">
    <TabControl.Template><ControlTemplate TargetType="TabControl"><Grid KeyboardNavigation.TabNavigation="Local"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions><ScrollViewer Grid.Row="0" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Disabled" CanContentScroll="False" Focusable="False"><TabPanel IsItemsHost="True" KeyboardNavigation.TabIndex="1"/></ScrollViewer><ContentPresenter Grid.Row="1" ContentSource="SelectedContent"/></Grid></ControlTemplate></TabControl.Template>
   </TabControl>
  </DockPanel>
  <Grid Grid.Row="4" Background="#071827"><Grid.ColumnDefinitions><ColumnDefinition Width="235" MinWidth="150"/><ColumnDefinition Width="5"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
   <Border Grid.Column="0" Background="#0A1D2E" BorderBrush="#27485F" BorderThickness="1" CornerRadius="5" Margin="1,1,0,1">
    <DockPanel>
     <TextBlock DockPanel.Dock="Top" Text="  &#x25C9;  EVENT SOURCES" FontWeight="SemiBold" Foreground="#8EDBFF" FontSize="12" Padding="7,12" Background="#112D43"/>
     <TreeView x:Name="LogTree" Background="#0A1D2E" BorderThickness="0" Margin="8" Foreground="#E8F4FF"/>
    </DockPanel>
   </Border>
   <GridSplitter Grid.Column="1" Width="5" Background="#31516A" HorizontalAlignment="Stretch"/>
   <Border Grid.Column="2" Background="#071827" BorderBrush="#27485F" BorderThickness="1" CornerRadius="5" Margin="0,1,1,1">
    <Grid><Grid.RowDefinitions><RowDefinition Height="38"/><RowDefinition Height="*" MinHeight="120"/><RowDefinition Height="5"/><RowDefinition Height="220" MinHeight="110"/></Grid.RowDefinitions>
     <Grid Grid.Row="0" Background="#102B40" Margin="1,1,1,0">
      <Grid.ColumnDefinitions><ColumnDefinition Width="158"/><ColumnDefinition Width="100"/><ColumnDefinition Width="72"/><ColumnDefinition Width="130"/><ColumnDefinition Width="130"/><ColumnDefinition Width="*"/><ColumnDefinition Width="58"/></Grid.ColumnDefinitions>
      <TextBox x:Name="FilterTime" Grid.Column="0" Margin="3,5" ToolTip="Date/time range: 2026-10-28--2026-10-25 or 2026-10-28 18:50--2026-10-25 18:25; single dates and partial text also work" VerticalContentAlignment="Center" />
      <TextBox x:Name="FilterLevel" Grid.Column="1" Margin="3,5" ToolTip="Filter Level" VerticalContentAlignment="Center" />
      <TextBox x:Name="FilterID" Grid.Column="2" Margin="3,5" ToolTip="Event IDs or inclusive ranges separated by commas (e.g. 1,34,6001-6009)" VerticalContentAlignment="Center" />
      <TextBox x:Name="FilterSource" Grid.Column="3" Margin="3,5" ToolTip="Filter Source" VerticalContentAlignment="Center" />
      <TextBox x:Name="FilterComputer" Grid.Column="4" Margin="3,5" ToolTip="Filter Computer" VerticalContentAlignment="Center" />
      <TextBox x:Name="FilterMessage" Grid.Column="5" Margin="3,5" ToolTip="Filter Message" VerticalContentAlignment="Center" />
      <Button x:Name="BtnClearFilters" Grid.Column="6" Content="Clear" Style="{StaticResource ActionButton}" Margin="3,5" Padding="4,2" ToolTip="Clear all six column filters"/>
     </Grid>
     <DataGrid x:Name="EventGrid" Grid.Row="1" ItemsSource="{x:Null}" AlternationCount="2" Margin="1">
      <DataGrid.Columns>
       <DataGridTextColumn Header="Time Created" Binding="{Binding Time}" Width="158" ElementStyle="{StaticResource EchoCellText}"/>
       <DataGridTemplateColumn Header="Level" SortMemberPath="Level" Width="100"><DataGridTemplateColumn.CellTemplate><DataTemplate>
        <StackPanel Orientation="Horizontal"><TextBlock Text="{Binding Symbol}" Foreground="{Binding LevelBrush}" FontWeight="Bold" Margin="0,0,6,0"/><TextBlock Text="{Binding Level}" Style="{StaticResource EchoCellText}"/></StackPanel>
       </DataTemplate></DataGridTemplateColumn.CellTemplate></DataGridTemplateColumn>
       <DataGridTextColumn Header="Event ID" Binding="{Binding ID}" Width="72" ElementStyle="{StaticResource EchoCellText}"/>
       <DataGridTextColumn Header="Source" Binding="{Binding Source}" Width="130" ElementStyle="{StaticResource EchoCellText}"/>
       <DataGridTextColumn Header="Computer" Binding="{Binding Computer}" Width="130" ElementStyle="{StaticResource EchoCellText}"/>
       <DataGridTextColumn Header="Message" Binding="{Binding MessagePreview}" Width="*" MinWidth="150" ElementStyle="{StaticResource EchoCellText}"/>
      </DataGrid.Columns>
     </DataGrid>
     <GridSplitter Grid.Row="2" Height="5" HorizontalAlignment="Stretch" Background="#31516A"/>
     <Grid Grid.Row="3"><Grid.RowDefinitions><RowDefinition Height="33"/><RowDefinition Height="*"/></Grid.RowDefinitions>
      <DockPanel Grid.Row="0" Background="#102B40">
       <Button x:Name="BtnCopy" DockPanel.Dock="Right" Style="{StaticResource ActionButton}" Content="&#x25A3; Copy" Padding="11,3"/>
       <TabControl x:Name="DetailTabs" BorderThickness="0" Background="#102B40">
        <TabItem Header="Event Details"/><TabItem Header="XML View"/>
       </TabControl>
      </DockPanel>
      <Grid Grid.Row="1" Margin="12,8"><Grid.ColumnDefinitions><ColumnDefinition Width="265"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
       <StackPanel Grid.Column="0">
        <TextBlock Text="Time Created:" Foreground="#8AAEC5"/><TextBlock x:Name="DetailTime" Margin="0,0,0,7"/>
        <TextBlock Text="Level / Event ID:" Foreground="#8AAEC5"/><TextBlock x:Name="DetailLevel" Margin="0,0,0,7"/>
        <TextBlock Text="Source:" Foreground="#8AAEC5"/><TextBlock x:Name="DetailSource" TextTrimming="CharacterEllipsis" Margin="0,0,0,7"/>
        <TextBlock Text="Computer:" Foreground="#8AAEC5"/><TextBlock x:Name="DetailComputer" TextTrimming="CharacterEllipsis"/>
       </StackPanel>
       <Border Grid.Column="1" Background="#0E293D" BorderBrush="#31516A" BorderThickness="1" CornerRadius="5" Margin="6,0,0,0">
        <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" Margin="9">
         <TextBlock x:Name="DetailMessage" TextWrapping="Wrap" Foreground="#E6F4FF" FontSize="12"/>
        </ScrollViewer>
       </Border>
      </Grid>
     </Grid>
    </Grid>
   </Border>
  </Grid>
  <Border Grid.Row="5" Background="#061A2C" BorderBrush="#1C405A" BorderThickness="1,1,0,0">
   <DockPanel Margin="10,4"><TextBlock x:Name="StatusText" Text="Ready" Foreground="#8FD4FF" VerticalAlignment="Center"/>
    <ProgressBar x:Name="BusyBar" Width="130" Height="5" DockPanel.Dock="Right" IsIndeterminate="True" Visibility="Collapsed" Margin="10,5" Foreground="#24A9F8"/>
   </DockPanel>
  </Border>
 </Grid>
</Window>
'@
$reader=New-Object System.Xml.XmlNodeReader $xaml
$script:Window=[Windows.Markup.XamlReader]::Load($reader)
$names=@('BrandIcon','VersionText','NavEvents','NavExport','NavSettings','BtnRefresh','BtnStop','BtnOpenSDDC','TimeFilter','LevelPicker','LevelPopup','LevelCritical','LevelError','LevelWarning','LevelInformation','LevelVerbose','LevelAll','LevelNone','EventCount','SearchBox','FilterTime','FilterLevel','FilterID','FilterSource','FilterComputer','FilterMessage','BtnClearFilters','BtnAddNode','NodeTabs','LogTree','EventGrid','BtnCopy','DetailTabs','DetailTime','DetailLevel','DetailSource','DetailComputer','DetailMessage','StatusText','BusyBar')
foreach($n in $names){Set-Variable -Name $n -Scope Script -Value $script:Window.FindName($n)}
$EventGrid.ItemsSource=$script:VisibleItems
$VersionText.Text="v$script:Version"
$BtnStop.IsEnabled=$false

# Embed artwork so this remains a single .ps1 deployment.
$script:LogoB64=''
try {
 $bytes=[Convert]::FromBase64String($script:LogoB64)
 $stream=New-Object IO.MemoryStream(,$bytes)
 $bitmap=New-Object System.Windows.Media.Imaging.BitmapImage
 $bitmap.BeginInit();$bitmap.CacheOption=[Windows.Media.Imaging.BitmapCacheOption]::OnLoad;$bitmap.StreamSource=$stream;$bitmap.EndInit();$bitmap.Freeze()
 $BrandIcon.Source=$bitmap;$stream.Dispose()
} catch { }

function Set-Status([string]$message){$StatusText.Text=$message}
function New-TreeNode([string]$name,[string]$tag,[string]$icon=([string][char]0x25A3)){
 $node=New-Object System.Windows.Controls.TreeViewItem
 $header=New-Object System.Windows.Controls.TextBlock
 $header.Text=$name
 $header.TextTrimming=[Windows.TextTrimming]::CharacterEllipsis
 $binding=New-Object Windows.Data.Binding('Foreground')
 $binding.Source=$node
 [void]$header.SetBinding([Windows.Controls.TextBlock]::ForegroundProperty,$binding)
 $node.Header=$header
 $node.Tag=$tag
 $node.ToolTip=$name
 return $node
}
function Add-LogHierarchy([Windows.Controls.TreeViewItem]$root,[string]$name,[string]$path,[hashtable]$cache){
 # Event Viewer hierarchy: hyphens and slashes separate levels, except Hyper-V.
 # Keep the full original channel name ONLY in the terminal leaf Tag.
 # Example: Microsoft-Windows-AppV-Client/Admin -> Microsoft > Windows > AppV > Client > Admin
 # Preserve Hyper-V as one hierarchy segment while splitting other hyphens/slashes.
 $safeName=[regex]::Replace($name,'(?i)Hyper-V','Hyper~V')
 $parts=@($safeName -split '[-/]' | Where-Object {-not [string]::IsNullOrWhiteSpace($_)} | ForEach-Object {$_ -replace '~','-'})
 if($parts.Count -eq 0){return}
 $parent=$root
 $key=''
 for($i=0;$i -lt $parts.Count;$i++){
  $part=[string]$parts[$i]
  $key += '/' + $part.ToLowerInvariant()
  $isLast=($i -eq $parts.Count-1)
  if(-not $cache.ContainsKey($key)){
   $node=New-TreeNode $part '' ([string][char]0x25B8)
   [void]$parent.Items.Add($node)
   $cache[$key]=$node
  }
  $parent=$cache[$key]
  if($isLast){
   # A channel can itself be the parent of other channels; retain its log path.
   $parent.Tag=$path
   $parent.ToolTip=$name
  }
 }
}
function Add-Session([string]$name,[string]$kind,[string]$path='', [string[]]$files=@(),[string]$groupColor=''){
 $key=[guid]::NewGuid().ToString('N')
 $script:Sessions[$key]=[pscustomobject]@{Name=$name;Kind=$kind;Path=$path;Files=@($files);Key=$key;Manual=$false}
 $tab=New-Object System.Windows.Controls.TabItem
 $tabName=if($kind -eq 'offline'){"$( [char]0x25A3 )  $name"}elseif($kind -eq 'correlate'){([string][char]0x25C7 + '  CORRELATE ALL NODES')}else{"$( [char]0x25A4 )  $name"}
 $tabHeader=New-Object Windows.Controls.TextBlock
 $tabHeader.Text=$tabName
 $tabStyle=New-Object System.Windows.Style([Windows.Controls.TextBlock])
 [void]$tabStyle.Setters.Add((New-Object Windows.Setter([Windows.Controls.TextBlock]::ForegroundProperty,([Windows.Media.BrushConverter]::new().ConvertFromString('#E2F4FF')))))
 $tabSelected=New-Object Windows.DataTrigger
 $tabSelected.Binding=New-Object Windows.Data.Binding('IsSelected')
 $tabSelected.Binding.RelativeSource=New-Object Windows.Data.RelativeSource([Windows.Data.RelativeSourceMode]::FindAncestor,[Windows.Controls.TabItem],1)
 $tabSelected.Value=$true
 [void]$tabSelected.Setters.Add((New-Object Windows.Setter([Windows.Controls.TextBlock]::FontWeightProperty,[Windows.FontWeights]::Bold)))
 [void]$tabStyle.Triggers.Add($tabSelected)
 $tabHeader.Style=$tabStyle
 $tab.Header=$tabHeader
 $tab.Tag=$key;$tab.ToolTip="$kind : $name"
 if($kind -eq 'offline'){$tab.Background=([Windows.Media.BrushConverter]::new().ConvertFromString($(if($groupColor){$groupColor}else{'#126A8A'})))}
 $tab.Add_PreviewMouseRightButtonUp({
  param($sender,$e)
  $session=$script:Sessions[[string]$sender.Tag]
  if($session -and ($session.Manual -or $session.Kind -eq 'offline')){
   $menu=New-Object Windows.Controls.ContextMenu
   $close=New-Object Windows.Controls.MenuItem
   $close.Header="Close tab: $($session.Name)"
   $close.Tag=[string]$sender.Tag
   $close.Add_Click({
    param($menuSender,$menuEvent)
    $id=[string]$menuSender.Tag
    $target=@($NodeTabs.Items | Where-Object {[string]$_.Tag -eq $id}) | Select-Object -First 1
    if($target){
     if($script:CurrentJob){Stop-Query}
     $NodeTabs.Items.Remove($target)
     $script:Sessions.Remove($id)
     if($NodeTabs.Items.Count -gt 0 -and -not $NodeTabs.SelectedItem){$NodeTabs.SelectedIndex=0}
     Set-Status 'Computer tab closed'
    }
   })
   [void]$menu.Items.Add($close)
   $sender.ContextMenu=$menu
   $menu.IsOpen=$true
   $e.Handled=$true
  }
 })
 [void]$NodeTabs.Items.Add($tab)
 return $tab
}
function Get-Session {if($NodeTabs.SelectedItem){return $script:Sessions[[string]$NodeTabs.SelectedItem.Tag]}return $null}
function Get-LogName([string]$file){
 $n=[IO.Path]::GetFileNameWithoutExtension($file)
 $n=$n -replace '%4','/' -replace '_','-'
 return $n
}
# Match only event channels associated with features that are actually installed.
# ServerManager is available on Windows Server; optional-feature fallback supports clients.
function Get-InstalledEventFeatureGroups([string]$computer,[string]$kind){
 $installed=@{}
 if($kind -ne 'live'){return $installed}
 $features=@()
 try {
  $args=@{ErrorAction='Stop'}
  if($computer -and $computer -ne $env:COMPUTERNAME){$args.ComputerName=$computer}
  $features=@(Get-WindowsFeature @args | Where-Object {$_.Installed} | Select-Object -ExpandProperty Name)
 } catch {
  if(-not $computer -or $computer -eq $env:COMPUTERNAME){
   try {$features=@(Get-WindowsOptionalFeature -Online -ErrorAction Stop | Where-Object {$_.State -eq 'Enabled'} | Select-Object -ExpandProperty FeatureName)} catch {}
  }
 }
 $featureNames=@($features | ForEach-Object {[string]$_})
 $definitions=@(
  @{Title='Hyper-V';Features=@('Hyper-V','Microsoft-Hyper-V','Microsoft-Hyper-V-All');Channels=@('Microsoft-Windows-Hyper-V-*','Microsoft-Windows-VmSwitch/*','Microsoft-Windows-VHDMP/*')},
  @{Title='Failover Clustering';Features=@('Failover-Clustering','FailoverCluster-FullServer');Channels=@('Microsoft-Windows-FailoverClustering/*','Microsoft-Windows-Cluster*/*')},
  @{Title='Storage Spaces / S2D';Features=@('FS-FileServer','Storage-Services','Storage-Replica');Channels=@('Microsoft-Windows-StorageSpaces-*/*','Microsoft-Windows-StorageReplica/*')},
  @{Title='Active Directory Domain Services';Features=@('AD-Domain-Services','DirectoryServices-DomainController');Channels=@('Directory Service','Microsoft-Windows-ActiveDirectory*/*','Microsoft-Windows-DirectoryServices*/*')},
  @{Title='DNS Server';Features=@('DNS','DNS-Server-Full-Role');Channels=@('DNS Server','Microsoft-Windows-DNSServer/*')},
  @{Title='DHCP Server';Features=@('DHCPServer','DHCPServer-Tools');Channels=@('Microsoft-Windows-DHCP-Server/*')},
  @{Title='Remote Desktop Services';Features=@('RDS-RD-Server','RDS-Connection-Broker','RDS-Web-Access');Channels=@('Microsoft-Windows-TerminalServices-*/*','Microsoft-Windows-RemoteDesktopServices-*/*')},
  @{Title='Web Server (IIS)';Features=@('Web-Server','IIS-WebServerRole');Channels=@('Microsoft-Windows-IIS-*/*','Microsoft-Windows-WAS/*','Microsoft-Windows-W3SVC*/*')},
  @{Title='Windows Server Backup';Features=@('Windows-Server-Backup','WindowsServerBackup');Channels=@('Microsoft-Windows-Backup/*')},
  @{Title='Containers';Features=@('Containers','Containers-DisposableClientVM');Channels=@('Microsoft-Windows-Containers-*/*','Microsoft-Windows-Host-Network-Service/*')}
 )
 foreach($definition in $definitions){
  foreach($feature in $definition.Features){
   if($featureNames -contains $feature){$installed[$definition.Title]=$definition.Channels;break}
  }
 }
 return $installed
}
function Populate-Tree {
 $script:LoadingTree=$true
 try {
  $LogTree.Items.Clear()
  $s=Get-Session
  if(-not $s){return}
  $script:CurrentSession=$s;$script:CurrentLog=$null
  $windows=New-TreeNode 'Windows Logs' '' ([string][char]0x25A3)
  $services=New-TreeNode 'Applications and Services Logs' '' ([string][char]0x25A3)
  $installedRoot=New-TreeNode 'Installed Features' '' ([string][char]0x25A3)
  $featureGroups=Get-InstalledEventFeatureGroups $s.Name $s.Kind
  $featureNodes=@{}
  $serviceFolders=@{}
  $featureFolders=@{}
  $available=@()
  if($s.Kind -eq 'offline'){
   foreach($file in $s.Files){$available+=,[pscustomobject]@{Name=(Get-LogName $file);Path=$file}}
   $TimeFilter.SelectedIndex=0
  } else {
   # Local and remote channel discovery; only logs actually present on the target.
   try {
    if($s.Kind -eq 'live' -and $s.Name -ne $env:COMPUTERNAME){
     $logs=@(Get-WinEvent -ListLog * -ComputerName $s.Name -ErrorAction Stop | Where-Object { $_.IsEnabled } | Select-Object -ExpandProperty LogName)
    } else {
     $logs=@(Get-WinEvent -ListLog * -ErrorAction Stop | Where-Object { $_.IsEnabled } | Select-Object -ExpandProperty LogName)
    }
    foreach($log in $logs){$available+=,[pscustomobject]@{Name=[string]$log;Path=[string]$log}}
   } catch {Set-Status "Could not list logs on $($s.Name): $($_.Exception.Message)"}
   if($s.Kind -eq 'correlate'){
    # Correlation uses a shared channel; the actual query includes each live node.
    $available=@('Application','System','Setup','Microsoft-Windows-FailoverClustering/Operational','Microsoft-Windows-StorageSpaces-Driver/Operational' | ForEach-Object {[pscustomobject]@{Name=$_;Path=$_}})
   }
  }
  foreach($log in @($available | Sort-Object Name)){
   $name=[string]$log.Name;$path=[string]$log.Path
   $item=New-TreeNode $name $path ([string][char]0x25A3)
   if($name -in @('Application','Security','System','Setup','ForwardedEvents')){
    [void]$windows.Items.Add($item)
   } else {
    $matched=$false
    foreach($featureName in @($featureGroups.Keys | Sort-Object)){
     foreach($pattern in $featureGroups[$featureName]){
      if($name -like $pattern){
       if(-not $featureNodes.ContainsKey($featureName)){
        $groupNode=New-TreeNode $featureName '' ([string][char]0x25A3)
        $featureNodes[$featureName]=$groupNode
        [void]$installedRoot.Items.Add($groupNode)
       }
       if(-not $featureFolders.ContainsKey($featureName)){$featureFolders[$featureName]=@{}}
       $displayName=$name
       $wildcardIndex=$pattern.IndexOf('*')
       if($wildcardIndex -gt 0){
        $featurePrefix=$pattern.Substring(0,$wildcardIndex)
        if($displayName.StartsWith($featurePrefix,[StringComparison]::OrdinalIgnoreCase)){
         $displayName=($displayName.Substring($featurePrefix.Length) -replace '^[-/]+','')
        }
       }
       if([string]::IsNullOrWhiteSpace($displayName)){$displayName=$name}
       Add-LogHierarchy $featureNodes[$featureName] $displayName $path $featureFolders[$featureName]
       $matched=$true
       break
      }
     }
     if($matched){break}
    }
    if(-not $matched){
     Add-LogHierarchy $services $name $path $serviceFolders
    }
   }

  }
  if($installedRoot.Items.Count){[void]$LogTree.Items.Add($installedRoot)}
  [void]$LogTree.Items.Add($windows)
  if($services.Items.Count){[void]$LogTree.Items.Add($services)}
  if($installedRoot.Items.Count){$installedRoot.IsExpanded=$true}
  $windows.IsExpanded=$true
  if($windows.Items.Count){$windows.Items[0].IsSelected=$true}
  elseif($services.Items.Count){$services.IsExpanded=$true;$services.Items[0].IsSelected=$true}
  Set-Status "Selected $($s.Name) | $($available.Count) available event logs"
 } finally {$script:LoadingTree=$false}
 # On-demand query only after tree has finished building.
 if($LogTree.SelectedItem -and $LogTree.SelectedItem.Tag){Start-Query}
}
function Get-Since {
 switch($TimeFilter.SelectedIndex){
  0{return $null}
  1{return (Get-Date).AddHours(-1)}
  2{return (Get-Date).AddHours(-6)}
  3{return (Get-Date).AddDays(-1)}
  4{return (Get-Date).AddDays(-7)}
  5{return (Get-Date).AddDays(-30)}
  default{return $null}
 }
}
function Convert-Event($ev){
 $level=[string]$ev.LevelDisplayName
 if(-not $level){$level='Information'}
 $symbol=[string][char]0x25CF;$color='#49BDF5'
 switch -Regex ($level){
  '^Critical$'{$symbol=[string][char]0x2716;$color='#FF4671';break}
  '^Error$'{$symbol=[string][char]0x2716;$color='#FF5267';break}
  '^Warning$'{$symbol=[string][char]0x25B2;$color='#FFCB43';break}
  '^Verbose$'{$symbol=[string][char]0x25CB;$color='#9BB8CD';break}
 }
 $message=try{[string]$ev.Message}catch{''}
 if(-not $message){$message='(Message unavailable)'}
 $source=if($ev.ProviderName){[string]$ev.ProviderName}else{'Unknown'}
 return [pscustomobject]@{
  Time=if($ev.TimeCreated){$ev.TimeCreated.ToString('yyyy-MM-dd HH:mm:ss')}else{''}
  Level=$level;Symbol=$symbol;LevelBrush=([Windows.Media.BrushConverter]::new().ConvertFromString($color));ID=[int]$ev.Id;Source=$source
  Computer=[string]$ev.MachineName;Message=$message;MessagePreview=($message -replace "[\r\n]+"," ");Log=[string]$ev.LogName
  XML=[string]$ev.XML
 }
}
function Set-Busy([bool]$busy){
 $BusyBar.Visibility=if($busy){'Visible'}else{'Collapsed'}
 $BtnStop.IsEnabled=$busy
 $BtnRefresh.IsEnabled=(-not $busy)
}
function Stop-Query {
 param([bool]$Silent=$false)
 if($script:CurrentJob){
  try{Stop-Job -Job $script:CurrentJob -ErrorAction SilentlyContinue}catch{}
  try{Remove-Job -Job $script:CurrentJob -Force -ErrorAction SilentlyContinue}catch{}
  $script:CurrentJob=$null
 }
 if($script:JobTimer){$script:JobTimer.Stop()}
 Set-Busy $false
 if(-not $Silent){Set-Status 'Query cancelled'}
}
function Start-Query {
 if($script:LoadingTree){return}
 $s=Get-Session
 if(-not $s){return}
 $item=$LogTree.SelectedItem
 if(-not $item -or -not $item.Tag){return}
 $path=[string]$item.Tag
 if($script:CurrentJob){Stop-Query -Silent $true}
 $script:CurrentLog=$path
 $script:Items.Clear();$script:VisibleItems.Clear()
 $DetailMessage.Text='';$DetailTime.Text='';$DetailLevel.Text='';$DetailSource.Text='';$DetailComputer.Text=''
 $EventCount.Text='Events (0)'
 $since=Get-Since
 $nodes=@()
 if($s.Kind -eq 'correlate'){
  $nodes=@($script:Sessions.Values | Where-Object {$_.Kind -eq 'live'} | ForEach-Object {$_.Name})
 }elseif($s.Kind -eq 'live'){$nodes=@($s.Name)}
 $script:CurrentJob=Start-Job -ArgumentList $s.Kind,$path,$nodes,$since,$script:MaxEvents -ScriptBlock {
  param($kind,$log,$targets,$from,$max)
  function Convert-Record($record){
   [pscustomobject]@{
    TimeCreated=$record.TimeCreated;LevelDisplayName=$record.LevelDisplayName
    Id=$record.Id;ProviderName=$record.ProviderName;MachineName=$record.MachineName
    Message=$record.Message;LogName=$record.LogName;XML=try{$record.ToXml()}catch{''}
   }
  }
  if($kind -eq 'offline'){
   $f=@{Path=$log}
   if($from){$f.StartTime=$from}
   try{Get-WinEvent -FilterHashtable $f -MaxEvents $max -ErrorAction Stop | ForEach-Object {Convert-Record $_}}catch{
    if($_.FullyQualifiedErrorId -notmatch 'NoMatchingEventsFound' -and $_.Exception.Message -notmatch 'No events were found'){Write-Error "${log}: $($_.Exception.Message)"}
   }
  }else{
   foreach($node in $targets){
    $f=@{LogName=$log}
    if($from){$f.StartTime=$from}
    try{
     if($node -eq $env:COMPUTERNAME){Get-WinEvent -FilterHashtable $f -MaxEvents $max -ErrorAction Stop | ForEach-Object {Convert-Record $_}}
     else{Get-WinEvent -ComputerName $node -FilterHashtable $f -MaxEvents $max -ErrorAction Stop | ForEach-Object {Convert-Record $_}}
    }catch{
     if($_.FullyQualifiedErrorId -notmatch 'NoMatchingEventsFound' -and $_.Exception.Message -notmatch 'No events were found'){Write-Error "${node} / ${log}: $($_.Exception.Message)"}
    }
   }
  }
 }
 Set-Busy $true
 Set-Status "Querying $($s.Name) / $([IO.Path]::GetFileName($path))..."
 if($script:JobTimer){$script:JobTimer.Stop()}
 $script:JobTimer=New-Object Windows.Threading.DispatcherTimer
 $script:JobTimer.Interval=[TimeSpan]::FromMilliseconds(250)
 $script:JobTimer.Add_Tick({
  if(-not $script:CurrentJob){$script:JobTimer.Stop();return}
  if($script:CurrentJob.State -in @('Completed','Failed','Stopped')){
   $script:JobTimer.Stop()
   $job=$script:CurrentJob;$script:CurrentJob=$null
   $errors=@($job.ChildJobs | ForEach-Object {$_.Error} | ForEach-Object {$_.ToString()})
   try{$events=@(Receive-Job -Job $job -ErrorAction SilentlyContinue)}catch{$events=@()}
   Remove-Job -Job $job -Force -ErrorAction SilentlyContinue
   foreach($ev in $events){
    if($null -eq $ev){continue}
    try{$script:Items.Add((Convert-Event $ev))}catch{$errors+= "Event conversion: $($_.Exception.Message)"}
   }
   Set-Busy $false
   Apply-Filter
   if($errors.Count){Set-Status "Loaded $($script:Items.Count) events. Query error: $($errors[0])"}
   else{Set-Status "Complete | $($script:CurrentLog) | $($script:Items.Count) events (max $script:MaxEvents per node)"}
  }
 })
 $script:JobTimer.Start()
}
function Test-EchoTimeFilter([string]$filter,[string]$eventTime){
 $filter=$filter.Trim()
 if(-not $filter){return $true}
 # Two ISO dates/times separated by --; order does not matter.
 if($filter -match '^(?<a>\d{4}-\d{2}-\d{2}(?:[ T]\d{1,2}:\d{2}(?::\d{2})?)?)\s*--\s*(?<b>\d{4}-\d{2}-\d{2}(?:[ T]\d{1,2}:\d{2}(?::\d{2})?)?)$'){
  $a=[datetime]::MinValue;$b=[datetime]::MinValue;$actual=[datetime]::MinValue
  if(-not ([datetime]::TryParse($Matches['a'],[ref]$a) -and [datetime]::TryParse($Matches['b'],[ref]$b) -and [datetime]::TryParse($eventTime,[ref]$actual))){return $false}
  $start=$a;$end=$b
  if($start -gt $end){$start=$b;$end=$a}
  # Date-only endpoints cover the entire calendar day, inclusively.
  if($Matches['a'].Length -eq 10 -and $a -eq $end){$end=$end.AddDays(1).AddTicks(-1)}
  if($Matches['b'].Length -eq 10 -and $b -eq $end){$end=$end.AddDays(1).AddTicks(-1)}
  return ($actual -ge $start -and $actual -le $end)
 }
 return ($eventTime.IndexOf($filter,[StringComparison]::OrdinalIgnoreCase) -ge 0)
}
function Apply-Filter {
 $term=$SearchBox.Text.Trim()
 $enabled=@{}
 foreach($name in @('Critical','Error','Warning','Information','Verbose')){
  $control=Get-Variable -Name ('Level'+$name) -ValueOnly
  $enabled[$name]=($control.IsChecked -eq $true)
 }
 $script:VisibleItems.Clear()
 foreach($item in $script:Items){
  $eventLevel=[string]$item.Level
  if(-not $enabled.ContainsKey($eventLevel) -or -not $enabled[$eventLevel]){continue}
  if($term -and -not ("$($item.Message) $($item.ID) $($item.Source) $($item.Computer) $($item.Log)" -like "*$term*")){continue}
  $columnValues=@([string]$item.Time,[string]$item.Level,[string]$item.ID,[string]$item.Source,[string]$item.Computer,[string]$item.Message)
  $columnFilters=@($FilterTime.Text,$FilterLevel.Text,$FilterID.Text,$FilterSource.Text,$FilterComputer.Text,$FilterMessage.Text)
  $matchesColumns=$true
  for($i=0;$i -lt $columnFilters.Count;$i++){
   $value=[string]$columnFilters[$i]
   if([string]::IsNullOrWhiteSpace($value)){continue}
   # Comma-separated values are OR alternatives within a column; columns are ANDed.
   # Event ID is always an exact numeric match (never a substring match).
   $choices=@($value -split ',' | ForEach-Object {$_.Trim()} | Where-Object {$_ -ne ''})
   if($choices.Count -eq 0){continue}
   $matchedChoice=$false
   foreach($choice in $choices){
    if($i -eq 0){
     if(Test-EchoTimeFilter $choice $columnValues[$i]){$matchedChoice=$true;break}
    } elseif($i -eq 2){
     $actualID=0L
     if(-not [long]::TryParse($columnValues[$i],[ref]$actualID)){continue}
     if($choice -match '^(?<start>\d+)\s*-\s*(?<end>\d+)$'){
      $startID=0L;$endID=0L
      if([long]::TryParse($Matches['start'],[ref]$startID) -and [long]::TryParse($Matches['end'],[ref]$endID)){
       if($startID -gt $endID){$rangeStart=$endID;$rangeEnd=$startID}else{$rangeStart=$startID;$rangeEnd=$endID}
       if($actualID -ge $rangeStart -and $actualID -le $rangeEnd){$matchedChoice=$true;break}
      }
     } else {
      $wantedID=0L
      if([long]::TryParse($choice,[ref]$wantedID) -and $wantedID -eq $actualID){$matchedChoice=$true;break}
     }
    } elseif($columnValues[$i].IndexOf($choice,[StringComparison]::OrdinalIgnoreCase) -ge 0){$matchedChoice=$true;break}
   }
   if(-not $matchedChoice){$matchesColumns=$false;break}
  }
  if(-not $matchesColumns){continue}
  $script:VisibleItems.Add($item)
 }
 $EventCount.Text="Events ($($script:VisibleItems.Count))"
 $count=@($enabled.Values | Where-Object {$_}).Count
 $LevelPicker.Content=if($count -eq 5){'Levels: All'}elseif($count -eq 0){'Levels: None'}else{"Levels: $count selected"}
}
function Export-CSV {
 if(-not $script:VisibleItems.Count){[Windows.MessageBox]::Show('There are no displayed events to export.','ECHO')|Out-Null;return}
 $dlg=New-Object Microsoft.Win32.SaveFileDialog
 $dlg.Title='Export ECHO Events';$dlg.Filter='CSV files (*.csv)|*.csv';$dlg.FileName='ECHO-Events.csv';$dlg.AddExtension=$true
 try{
  if($dlg.ShowDialog($script:Window)){
   $script:VisibleItems | Select-Object Time,Level,ID,Source,Computer,Log,Message | Export-Csv -LiteralPath $dlg.FileName -NoTypeInformation -Encoding UTF8
   Set-Status "Exported $($script:VisibleItems.Count) events to $($dlg.FileName)"
  }
 }catch{[Windows.MessageBox]::Show("CSV export failed: $($_.Exception.Message)",'ECHO')|Out-Null}
}
function Show-EchoFolderBrowser([string]$initialPath=''){
 [xml]$browserXaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="ECHO - Select Folder" Width="680" Height="500" MinWidth="520" MinHeight="360"
        WindowStartupLocation="CenterOwner" Background="#091E30" Foreground="#FFFFFF">
 <Grid Margin="16">
  <Grid.RowDefinitions>
   <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/>
   <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/>
  </Grid.RowDefinitions>
  <TextBlock Grid.Row="0" Text="Select expanded SDDC collection folder" Foreground="#8EDBFF" FontSize="15" FontWeight="SemiBold" Margin="0,0,0,10"/>
  <Grid Grid.Row="1" Margin="0,0,0,10">
   <Grid.ColumnDefinitions><ColumnDefinition Width="120"/><ColumnDefinition Width="*"/><ColumnDefinition Width="70"/><ColumnDefinition Width="70"/></Grid.ColumnDefinitions>
   <ComboBox x:Name="BrowserDrives" Grid.Column="0" Margin="0,0,8,0" Background="#E1F3FF" Foreground="#000000"/>
   <TextBox x:Name="BrowserPath" Grid.Column="1" Margin="0,0,8,0" Padding="7,5" Background="#FFFFFF" Foreground="#000000"/>
   <Button x:Name="BrowserGo" Grid.Column="2" Content="Go" Margin="0,0,8,0" Padding="8,5"/>
   <Button x:Name="BrowserUp" Grid.Column="3" Content="Up" Padding="8,5"/>
  </Grid>
  <ListBox x:Name="BrowserFolders" Grid.Row="2" Background="#FFFFFF" Foreground="#000000" BorderBrush="#365B74" BorderThickness="1" FontSize="13"/>
  <TextBlock x:Name="BrowserStatus" Grid.Row="3" Foreground="#A3D8F5" Margin="0,8,0,8" TextWrapping="Wrap"/>
  <StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Right">
   <Button x:Name="BrowserCancel" Content="Cancel" Width="90" Padding="8,6" Margin="0,0,8,0"/>
   <Button x:Name="BrowserSelect" Content="Select Folder" Width="120" Padding="8,6" Background="#0879C9" Foreground="#FFFFFF"/>
  </StackPanel>
 </Grid>
</Window>
'@
 $browserReader=New-Object System.Xml.XmlNodeReader $browserXaml
 $browser=[Windows.Markup.XamlReader]::Load($browserReader)
 $browserReader.Close()
 $browser.Owner=$script:Window
 $driveList=$browser.FindName('BrowserDrives')
 $pathText=$browser.FindName('BrowserPath')
 $folderList=$browser.FindName('BrowserFolders')
 $status=$browser.FindName('BrowserStatus')
 $go=$browser.FindName('BrowserGo')
 $up=$browser.FindName('BrowserUp')
 $cancel=$browser.FindName('BrowserCancel')
 $select=$browser.FindName('BrowserSelect')
 $navigate={
  param([string]$target)
  $target=([string]$target).Trim()
  if([string]::IsNullOrWhiteSpace($target)){
   $status.Text='Enter a local or UNC folder path.'
   return $false
  }
  try{
   $target=[Environment]::ExpandEnvironmentVariables($target)
   if(-not [IO.Directory]::Exists($target)){
    $status.Text="Folder not found: $target"
    return $false
   }
   $resolved=[IO.Path]::GetFullPath($target)
   $directories=@([IO.Directory]::GetDirectories($resolved) | Sort-Object)
   $folderList.Items.Clear()
   foreach($directory in $directories){
    $folderItem=New-Object Windows.Controls.ListBoxItem
    $folderItem.Content=[IO.Path]::GetFileName($directory.TrimEnd([char[]]@([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)))
    $folderItem.Tag=$directory
    $folderItem.ToolTip=$directory
    $folderItem.Padding='7,5'
    [void]$folderList.Items.Add($folderItem)
   }
   $pathText.Text=$resolved
   $status.Text="$($directories.Count) folder(s). Double-click to open a folder, or select it and choose Select Folder."
   return $true
  }catch{
   $status.Text="Unable to open folder: $($_.Exception.Message)"
   return $false
  }
 }
 foreach($drive in @([IO.DriveInfo]::GetDrives() | Where-Object {$_.IsReady})){
  $driveItem=New-Object Windows.Controls.ComboBoxItem
  $driveItem.Content="$($drive.Name)  $($drive.VolumeLabel)"
  $driveItem.Tag=$drive.RootDirectory.FullName
  [void]$driveList.Items.Add($driveItem)
 }
 $driveList.Add_SelectionChanged({
  if($driveList.SelectedItem){[void](& $navigate ([string]$driveList.SelectedItem.Tag))}
 })
 $go.Add_Click({[void](& $navigate ([string]$pathText.Text))})
 $pathText.Add_KeyDown({
  if($_.Key -eq [Windows.Input.Key]::Enter){[void](& $navigate ([string]$pathText.Text))}
 })
 $folderList.Add_MouseDoubleClick({
  if($folderList.SelectedItem){[void](& $navigate ([string]$folderList.SelectedItem.Tag))}
 })
 $up.Add_Click({
  try{
   $current=New-Object IO.DirectoryInfo(([string]$pathText.Text).Trim())
   if($current.Parent){[void](& $navigate $current.Parent.FullName)}
  }catch{$status.Text="Unable to open parent folder: $($_.Exception.Message)"}
 })
 $cancel.Add_Click({$browser.DialogResult=$false;$browser.Close()})
 $select.Add_Click({
  $selectedPath=([string]$pathText.Text).Trim()
  if($folderList.SelectedItem){$selectedPath=[string]$folderList.SelectedItem.Tag}
  if([string]::IsNullOrWhiteSpace($selectedPath) -or -not [IO.Directory]::Exists($selectedPath)){
   $status.Text='Select an existing folder.'
   return
  }
  $browser.Tag=[IO.Path]::GetFullPath($selectedPath)
  $browser.DialogResult=$true
  $browser.Close()
 })
 $startPath=([string]$initialPath).Trim()
 if([string]::IsNullOrWhiteSpace($startPath) -or -not [IO.Directory]::Exists($startPath)){
  $startPath=[IO.Path]::GetPathRoot($env:SystemRoot)
 }
 [void](& $navigate $startPath)
 $pathText.Focus() | Out-Null
 $pathText.CaretIndex=$pathText.Text.Length
 if($browser.ShowDialog()){return [string]$browser.Tag}
 return $null
}
function Ask-SDDCPath {
 $dlg=New-Object Windows.Window
 $dlg.Title='ECHO - Open EVTX Folder'
 $dlg.Width=640;$dlg.Height=235;$dlg.ResizeMode='NoResize'
 $dlg.WindowStartupLocation='CenterOwner';$dlg.Owner=$script:Window
 $dlg.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#091E30')
 $dlg.Foreground=[Windows.Media.Brushes]::White
 $panel=New-Object Windows.Controls.StackPanel;$panel.Margin='20';$dlg.Content=$panel
 $heading=New-Object Windows.Controls.TextBlock
 $heading.Text='Enter the path to the expanded SDDC collection folder'
 $heading.FontSize=16;$heading.Foreground=[Windows.Media.Brushes]::LightSkyBlue
 $heading.Margin='0,0,0,8';[void]$panel.Children.Add($heading)
 $hint=New-Object Windows.Controls.TextBlock
 $hint.Text='The folder should contain one subfolder per node, with EVTX files in each node folder.'
 $hint.TextWrapping='Wrap';$hint.Margin='0,0,0,12';[void]$panel.Children.Add($hint)
 $pathInput=New-Object Windows.Controls.TextBox
 $pathInput.Padding='8';$pathInput.FontSize=13
 if(Test-Path -LiteralPath $script:SettingsFile){
  $previous=([string](Get-Content -LiteralPath $script:SettingsFile -Raw -ErrorAction SilentlyContinue)).Trim()
  if(-not [string]::IsNullOrWhiteSpace($previous) -and (Test-Path -LiteralPath $previous -PathType Container)){$pathInput.Text=$previous}
 }
 [void]$panel.Children.Add($pathInput)
 $buttons=New-Object Windows.Controls.StackPanel
 $buttons.Orientation='Horizontal';$buttons.HorizontalAlignment='Right';$buttons.Margin='0,14,0,0'
 [void]$panel.Children.Add($buttons)
 $browse=New-Object Windows.Controls.Button;$browse.Content='Browse...';$browse.Width=95;$browse.Padding='6'
 $browse.Margin='0,0,8,0';[void]$buttons.Children.Add($browse)
 $cancel=New-Object Windows.Controls.Button;$cancel.Content='Cancel';$cancel.Width=90;$cancel.Padding='6'
 $cancel.Margin='0,0,8,0';[void]$buttons.Children.Add($cancel)
 $ok=New-Object Windows.Controls.Button;$ok.Content='Open EVTX Folder';$ok.Width=115;$ok.Padding='6'
 $ok.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#0879C9')
 $ok.Foreground=[Windows.Media.Brushes]::White;[void]$buttons.Children.Add($ok)
 $browse.Add_Click({
  try{
   $selectedPath=([string]$pathInput.Text).Trim()
   $folder=Show-EchoFolderBrowser $selectedPath
   if($folder){$pathInput.Text=$folder}
   }catch{[Windows.MessageBox]::Show("Folder browser unavailable. Paste the folder path instead.`n$($_.Exception.Message)",'ECHO')|Out-Null}
 })
 $cancel.Add_Click({$dlg.DialogResult=$false;$dlg.Close()})
 $ok.Add_Click({
  $selectedPath=([string]$pathInput.Text).Trim()
  if([string]::IsNullOrWhiteSpace($selectedPath) -or -not (Test-Path -LiteralPath $selectedPath -PathType Container)){
   [Windows.MessageBox]::Show('The folder path does not exist. Please select an extracted SDDC collection folder.','ECHO')|Out-Null
   return
  }
  $pathInput.Text=$selectedPath
  $dlg.DialogResult=$true;$dlg.Close()
 })
 $dlg.Add_ContentRendered({$pathInput.Focus();$pathInput.SelectAll()})
 if($dlg.ShowDialog()){return ([string]$pathInput.Text).Trim()}
 return $null
}
function Open-SDDC {
 $root=Ask-SDDCPath
 if(-not $root){return}
 try{
  New-Item -ItemType Directory -Path $script:SettingsFolder -Force|Out-Null
  Set-Content -LiteralPath $script:SettingsFile -Value $root -Encoding UTF8
 }catch{}
 $added=0;$first=$null
 # Normalize the collection path so reopening the same folder keeps its group color.
 $groupKey=[IO.Path]::GetFullPath($root).TrimEnd([char]'\').ToLowerInvariant()
 if(-not $script:SDDCGroupColorByRoot.ContainsKey($groupKey)){
  $palette=$script:SDDCGroupColors
  # Shuffle the initial palette offset, then cycle distinct colors for successive collections.
  if($script:SDDCGroupColorByRoot.Count -eq 0){$script:SDDCGroupColorIndex=Get-Random -Minimum 0 -Maximum $palette.Count}
  $script:SDDCGroupColorByRoot[$groupKey]=$palette[$script:SDDCGroupColorIndex % $palette.Count]
  $script:SDDCGroupColorIndex++
 }
 $groupColor=[string]$script:SDDCGroupColorByRoot[$groupKey]
 try{
  $dirs=@(Get-ChildItem -LiteralPath $root -Directory -ErrorAction Stop)
  foreach($dir in $dirs){
   $files=@(Get-ChildItem -LiteralPath $dir.FullName -File -Filter '*.evtx' -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName)
   if(-not $files.Count){continue}
   $existing=@($script:Sessions.Values | Where-Object {$_.Kind -eq 'offline' -and $_.Path -eq $dir.FullName})
   if($existing.Count){continue}
   $tab=Add-Session -name $dir.Name -kind offline -path $dir.FullName -files $files -groupColor $groupColor
   $added++
   if(-not $first){$first=$tab}
  }
  if($added){
   $NodeTabs.SelectedItem=$first
   Set-Status "Imported $added SDDC node(s) from $root"
  }else{
   [Windows.MessageBox]::Show('No new node folders containing EVTX files were found directly inside the selected folder.','ECHO')|Out-Null
  }
 }catch{
  [Windows.MessageBox]::Show("SDDC import failed: $($_.Exception.Message)",'ECHO')|Out-Null
 }
}
function Add-RemoteNode {
 # Small WPF input window to avoid Microsoft.VisualBasic dependency.
 $dlg=New-Object Windows.Window
 $dlg.Title='Add remote computer';$dlg.Width=390;$dlg.Height=160;$dlg.WindowStartupLocation='CenterOwner';$dlg.Owner=$script:Window
 $dlg.Background=[Windows.Media.BrushConverter]::new().ConvertFromString('#0A2034');$dlg.Foreground=[Windows.Media.Brushes]::White
 $panel=New-Object Windows.Controls.StackPanel;$panel.Margin='18';$dlg.Content=$panel
 $lbl=New-Object Windows.Controls.TextBlock;$lbl.Text='Computer name or FQDN';$lbl.Margin='0,0,0,7';[void]$panel.Children.Add($lbl)
 $input=New-Object Windows.Controls.TextBox;$input.Padding='6';[void]$panel.Children.Add($input)
 $ok=New-Object Windows.Controls.Button;$ok.Content='Add computer';$ok.Width=120;$ok.Margin='0,10,0,0';$ok.HorizontalAlignment='Right';[void]$panel.Children.Add($ok)
 $ok.Add_Click({$dlg.DialogResult=$true;$dlg.Close()})
 if($dlg.ShowDialog()){
  $name=$input.Text.Trim()
  if($name -and -not @($script:Sessions.Values | Where-Object {$_.Kind -eq 'live' -and $_.Name -eq $name}).Count){
   $tab=Add-Session -name $name -kind live
   $script:Sessions[[string]$tab.Tag].Manual=$true
   $NodeTabs.SelectedItem=$tab
  }
 }
}
function Update-Details {
 $ev=$EventGrid.SelectedItem
 if(-not $ev){return}
 $DetailTime.Text=$ev.Time;$DetailLevel.Text="$($ev.Symbol) $($ev.Level)  /  $($ev.ID)"
 $DetailSource.Text=$ev.Source;$DetailComputer.Text=$ev.Computer
 if($DetailTabs.SelectedIndex -eq 1){$DetailMessage.Text=$ev.XML}
 else{$DetailMessage.Text=$ev.Message}
}

