 $selected=$_.NewValue
 if(-not $selected){return}
 if([string]::IsNullOrWhiteSpace([string]$selected.Tag)){
  if($selected.HasItems){$selected.IsExpanded=-not $selected.IsExpanded}
  return
 }
 Start-Query
})
