$BtnCopy.Add_Click({
 $ev=$EventGrid.SelectedItem
 if(-not $ev){Set-Status 'Select an event to copy.';return}
 try {
  if($DetailTabs.SelectedIndex -eq 1){
   # XML View: copy the complete XML payload, not just the visible portion.
   $copyText=[string]$ev.XML
   $copyLabel='event XML'
  }else{
   # Event Details: include all metadata shown in the details pane and the full message.
   $copyText=@(
    "Time Created: $($ev.Time)"
    "Level: $($ev.Level)"
    "Event ID: $($ev.ID)"
    "Source: $($ev.Source)"
    "Computer: $($ev.Computer)"
    ""
    "Message:"
    [string]$ev.Message
   ) -join [Environment]::NewLine
   $copyLabel='complete event details'
  }
  if([string]::IsNullOrEmpty($copyText)){Set-Status 'Selected event has no content to copy.';return}
  [Windows.Clipboard]::SetText($copyText)
  Set-Status "Copied $copyLabel to clipboard."
 }catch{
  [Windows.MessageBox]::Show("Unable to copy event: $($_.Exception.Message)",'ECHO')|Out-Null
 }
})
