using System;
using System.Runtime.InteropServices;
public static class EchoWindowChrome {
 [DllImport("dwmapi.dll")] public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attribute, ref int value, int size);
}
'@ -ErrorAction Stop
