  if($script:Window.Width -gt $work.Width){$script:Window.Width=$work.Width}
  if($script:Window.Height -gt $work.Height){$script:Window.Height=$work.Height}
  $script:Window.Left=$work.Left+[Math]::Max(0,($work.Width-$script:Window.ActualWidth)/2)
  $script:Window.Top=$work.Top+[Math]::Max(0,($work.Height-$script:Window.ActualHeight)/2)
 }catch{}
})
