# Load local tab first, then discover cluster nodes without importing FailoverClusters into PowerShell 7.
$local=Add-Session -name $env:COMPUTERNAME -kind live
$correlation=Add-Session -name 'CORRELATE ALL NODES' -kind correlate
try {
 if(Get-Command Get-ClusterNode -ErrorAction SilentlyContinue){
  foreach($node in @(Get-ClusterNode -ErrorAction Stop)){
   $name=[string]$node.Name
   if($name -and $name -ne $env:COMPUTERNAME -and -not @($script:Sessions.Values | Where-Object {$_.Kind -eq 'live' -and $_.Name -eq $name}).Count){
    [void](Add-Session -name $name -kind live)
   }
  }
 }
}catch{Set-Status 'Cluster discovery unavailable; local mode ready.'}
$NodeTabs.SelectedItem=$local
[void]$script:Window.ShowDialog()
